INSERT INTO `ob_formulaire` (`id`, `prenom`, `nom`, `sujet`, `message`, `email`, `entreprise`, `ip`, `time`, `date`, `phone`) VALUES
(8, 'Charlene', 'EHRET', 'Demende bon de commande', 'Bonjour, \r\n\r\nEn vue du prochain vide grenier de l\'Union qui se dÃ©roulera le dimanche 10  septembre, Pourriez vous m\'envoyez par mail un bon de commande .\r\n\r\nBien Cordialement\r\n\r\nCharlene EHRET', 'charlen050810@gmail.com', 'TROC UNION', '92.94.72.64', 1503406737, '', ''),
(9, 'Arnaud', 'Despouy', 'Devis Location Tireuse', 'Bonjour,\r\n\r\nPourrais-je avoir les prix de location pour une tireuse et les fÃ»ts que vous proposez Ã  la vente ? \r\nJe n\'ai pas trouvÃ© d\'informations sur le catalogue.\r\nLa location aurait lieu ce samedi 26 Aout 2017.\r\n\r\nMerci par avance.\r\nArnaud', 'arnaud.despouy@gmail.com', '', '185.16.252.3', 1503415528, '', ''),
(10, 'Marie', 'HOUBRON', 'devis location tireuse et futs ', 'Bonjour,\r\nNous souhaitons louer une ou deux tireuses avec futs pour une centaine de personnes avec un retrait le matin du vendredi 22 septembre et retour le lendemain matin. Que pouvez-vous nous proposer comme biÃ¨re blonde?\r\nL\'occasion est un Ã©vÃ¨nement professionnel dans le cadre de l\'anniversaire des 10 ans de notre entreprise. \r\nNous sommes basÃ© Ã  Grande.\r\n\r\nVous remerciant par avance pour votre retour.\r\n\r\nCordialement,\r\nMarie HOUBRON \r\n2Y INGÃ‰NIERIE', 'technicien@2yingenierie.com', '2Y INGENIERIE', '80.15.85.25', 1503490947, '', ''),
(11, 'Pascale', 'MATHIEU', 'Remboursement FÃ»t - ComitÃ© des fÃªtes de Montlaur', 'Bonjour,\r\nJe suis trÃ©soriÃ¨re au ComitÃ© des fÃªtes de Montlaur et aprÃ¨s un contrÃ´le des comptes, je me suis aperÃ§u qu\'il y avait une erreur sur le bon de retour des fÃ»ts de biÃ¨re. Nous avions commandÃ© 6 fÃ»ts. Quatre ont Ã©tÃ© consommÃ©s et 2 ont Ã©tÃ© retournÃ©s plein. \r\n\r\nJ\'ai pris contact avec vous il y a quelques semaines pour vous signaler le problÃ¨me. La personne en charge de comptabilitÃ© Ã©tait en congÃ©s et vous deviez nous contacter pour rÃ©gler le problÃ¨me. Actuellement nous restons dans l\'attente d\'une rÃ©ponse.\r\n\r\nCordialement\r\nMme MATHIEU Pascale\r\n', 'pmathieu68@gmail.com', 'COMITE DES FETES DE MONTLAUR', '193.55.90.147', 1504681664, '', ''),
(12, 'SÃ©bastien', 'Roux', 'Devis', 'Madame, Monsieur, bonjour,\r\n\r\nJe vous contacte au sujet de l\'association dont je suis membre, l\'association PoincarÃ© qui rÃ©unit les Ã©tudiants de la filiÃ¨re MathÃ©matiques de l\'universitÃ© Paul Sabatier.\r\nNous organisons rÃ©guliÃ¨rement des soirÃ©es et aimerions servir Ã  ces occasions des biÃ¨res de chez Occitanie Boissons. Nous aimerions donc en savoir plus sur vos tarifs : pouvez-vous nous faire parvenir par retour de mail une brochure ou un avis rapide ?\r\nNos besoins : 1 ou 2 fÃ»ts de biÃ¨re par soirÃ©e et une tireuse, pour des soirÃ©es qui se font tous les 1/2 mois.\r\n\r\nC\'est le vendeur du magasin La Voie MaltÃ©e qui m\'a conseillÃ© de vous contacter directement.\r\n\r\nD\'avance merci de votre rÃ©ponse,\r\nCordialement,\r\n\r\nSÃ©bastien Roux\r\nAssociation PoincarÃ©', 'sebi.roux@hotmail.fr', 'Association PoincarÃ©', '5.48.248.184', 1504889960, '', ''),
(13, 'Pascal', 'BOISGARD', 'biÃ¨res irlandaises', 'Bonjour, le comitÃ© des fÃªtes de Fonsegrives Ã  le projet de fÃªter la saint Patrick le 17 mars 2018. Dans l\'optique de cette soirÃ©e nous souhaiterions connaÃ®tre les diffÃ©rentes biÃ¨res Ã  la pression et les conditions : machines Ã  biÃ¨re, tables hautes etc.... que vous pourriez fournir.\r\nPar avance je vous en remercie.\r\nBien cordialement', 'comitedesfetes.fonsegrives@gmail.com', 'comitÃ© des fÃªtes Quint-Fonsegrives', '2a01:cb19:82f8:8e00:b5c6:f649:cdbc:ee61', 1505200519, '', ''),
(14, 'Johanna', 'Bousses', 'Demande de devis', 'Bonjour je cherche une location de tireuse de biere avec fur pour un mariage de 80 personnes.\r\nJe souhaiterai avoir vos tarif svp  c est pour 2018 \r\nMerci\r\nCordialement', 'johanna82@live.fr', '', '2a01:cb19:8169:5b00:c179:9b02:9610:bfcc', 1505375982, '', ''),
(15, 'Xavier', 'GOMBERT', 'Recherche distributeur', 'Bonjour;\r\n\r\nnous avons crÃ©e il y a 18 mois la Brasserie Artisanale de Sarlat et vendons nos biÃ¨res \"BrassÃ©e 24\" (tous circuits hors GMS) et \"Le FÃ»t Sarladais\" (GMS) localement.\r\n\r\nNotre production (qui correspond Ã  nos ventes) actuelle est de 800 hl/ an (dont 200 hl en fÃ»ts) et nous allons avoir Ã  compter de cette fin d\'annÃ©e une capacitÃ© de 1500 hl/an  .\r\n\r\nNous sommes Ã  la recherche de partenaires qui pourront nous aider Ã  nous dÃ©velopper rÃ©gionalement (Sud-Ouest) dans un premier temps. Si nous tenons Ã  maÃ®triser la distribution locale, nous souhaitons nous appuyer sur des partenaires rÃ©gionaux pour nous implanter hors de notre dÃ©partement.\r\n\r\nJe me tiens Ã  votre disposition pour toute information complÃ©mentaire.\r\n\r\nCordialement', 'brasseriejyx@gmail.com', 'BRASSERIE ARTISANALE DE SARLAT', '90.60.68.15', 1506005806, '', ''),
(16, 'Xavier', 'GOMBERT', 'Recherche distributeur', 'Bonjour;\r\n\r\nnous avons crÃ©e il y a 18 mois la Brasserie Artisanale de Sarlat et vendons nos biÃ¨res \"BrassÃ©e 24\" (tous circuits hors GMS) et \"Le FÃ»t Sarladais\" (GMS) localement.\r\n\r\nNotre production (qui correspond Ã  nos ventes) actuelle est de 800 hl/ an (dont 200 hl en fÃ»ts) et nous allons avoir Ã  compter de cette fin d\'annÃ©e une capacitÃ© de 1500 hl/an  .\r\n\r\nNous sommes Ã  la recherche de partenaires qui pourront nous aider Ã  nous dÃ©velopper rÃ©gionalement (Sud-Ouest) dans un premier temps. Si nous tenons Ã  maÃ®triser la distribution locale, nous souhaitons nous appuyer sur des partenaires rÃ©gionaux pour nous implanter hors de notre dÃ©partement.\r\n\r\nJe me tiens Ã  votre disposition pour toute information complÃ©mentaire.\r\n\r\nCordialement', 'brasseriejyx@gmail.com', 'BRASSERIE ARTISANALE DE SARLAT', '2a01:cb19:2e0:b600:e196:97c3:918e:71cc', 1506102168, '', ''),
(17, 'Salesses', 'Jean', 'Frenette', 'Bonjour\r\nPeut on acheter chez vous de la frÃªnette ?\r\nCordialement', 'jsalesses@gmail.com', '', '37.172.10.246', 1506171654, '', ''),
(18, 'Vincent', 'Capron', 'Informations', 'Bonjour , \r\nJe viens d\'ouvrir un restaurant belge , friterie a Seilh, prÃ¨s de blagnac, vendez vous des biÃ¨res belge aux professionnels, ? Auriez vous un catalogue avec vos produits et prix? \r\nMerci d\'avance \r\nCordialement \r\n\r\nVINCENT CAPRON\r\n0646362605\r\nChezlebelge1fois@gmail.com', 'chezlebelge1fois@gmail.com', 'Chez le belge une fois', '77.146.239.57', 1506443865, '', ''),
(19, 'BÃ©rengÃ¨re', 'DEMEAUTIS', 'DEMANDE DE RENSEIGNEMENTS', 'Bonjour, pour un mariage Ã  la fin du mois d\'octobre, j\'aurais souhaitÃ© louer une tireuse + vous commander une dizaine de fÃ»ts de biÃ¨re blonde.\r\nJ\'aurais souhaitÃ© connaÃ®tre vos conditions et tarifs svp,\r\nainsi que vos gammes de biÃ¨res blondes en conventionnel et en bio.\r\nIl est probable que nous effectuions la location du lundi 30 octobre au jeudi 02 novembre matin, ou au 03 novembre matin, ce qui serait plus pratique pour nous, selon les tarifs.\r\nMerci de votre attention.\r\nMon tÃ©l: 06 64 36 55 47', 'berengeredemeautis@yahoo.fr', '', '92.134.94.2', 1506694468, '', ''),
(20, 'christophe', 'dalla betta', 'tarif', 'bonjour \r\npourriez vous m\' envoyer les tarifs de fut de biÃ¨re 30 l \r\navec location d\'une tireuse\r\net les modalitÃ©s de rÃ©servation \r\nen vous remercient par avance', 'dallabetta.christophe@orange.fr', 'non', '82.125.186.218', 1507046918, '', ''),
